CREATE TABLE places_catalog_next (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  en TEXT NOT NULL DEFAULT '',
  cat TEXT NOT NULL,
  area TEXT NOT NULL,
  address TEXT NOT NULL,
  lat REAL,
  lng REAL,
  tags TEXT NOT NULL DEFAULT '[]',
  description TEXT NOT NULL DEFAULT '',
  story TEXT NOT NULL DEFAULT '',
  hours TEXT NOT NULL DEFAULT '',
  phone TEXT NOT NULL DEFAULT '',
  image TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'draft',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, address_en TEXT NOT NULL DEFAULT '', description_en TEXT NOT NULL DEFAULT '', story_en TEXT NOT NULL DEFAULT '', hours_en TEXT NOT NULL DEFAULT '',
  website TEXT NOT NULL DEFAULT ''
);
INSERT INTO places_catalog_next (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en) SELECT id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en FROM places;
DROP TABLE places;
ALTER TABLE places_catalog_next RENAME TO places;
CREATE INDEX places_status_idx ON places(status, cat, area);
UPDATE places SET status='draft' WHERE id IN ('afa','repairbike','reuse','coast','garden','youth','coastcare','bookshop','learn','shop','cafe','market')
 AND NOT EXISTS (SELECT 1 FROM articles WHERE status='published' AND place_id=places.id)
 AND NOT EXISTS (SELECT 1 FROM routes, json_each(routes.place_ids) WHERE routes.status='published' AND json_each.value=places.id);
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-4', '澳門旅遊大學教學餐廳 (UTM Educational Restaurant)', 'UTM Educational Restaurant', '食', '澳門半島', '澳門望廈山（望廈炮台斜坡）', 22.206858, 113.547919, '["食物"]', '收錄於《米芝蓮指南》的高等教育培訓餐廳，主打葡國菜及澳門土生菜（週六設土生菜自助餐），作爲餐飲教育基地在食材管理、惜食減廢及永續廚政上發揮示範作用', '', '週一至週六 12:00–15:00（最後落單14:00）、18:30–22:00（最後落單21:00）；週日及公眾假期休息', '+853 8598 3077', 'assets/catalog-f82c9f2b-fde8-5123-b092-4425d3b3fd16.webp', 'published', '2026-11-10T06:37:16.555Z', '2026-11-10T06:37:16.555Z', '', '', '', '', 'https://www2.utm.edu.mo/RESTAURANT/index.php/zh-tw/');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-5', '八分目 (Chakra Cafe / Chakra SPACE)', 'Chakra Cafe / Chakra SPACE', '食', '澳門半島', '水坑尾巷12號A 啓華大廈地下a室（即荷蘭園波鞋街（美心攝影）面向右方旁巷內直入步行數級樓梯立見） TRAVESSA DOS SANTOS NO.12 EDIF KAT VA RC-A MACAU, Taipa, Macau, 853', 22.195593019149428, 113.54428885973921, '["食物"]', '2015年開業至今的知名本土蔬食館及樂施會“良食推介”餐廳。主張“八分食材、二分調味”，晚市採用預約制無菜單料理以杜絕食材浪費，倡導日常物資與飲食“只取八成”的惜食減碳哲學。', '', '午間及輕食 12:30–18:00；晚餐（預約制）19:00–22:00；逢週日公休', '+853 6677 8669', 'assets/catalog-ae6b9384-5ade-54f1-9b9a-ea9d028da25a.webp', 'published', '2026-11-10T06:37:16.554Z', '2026-11-10T06:37:16.554Z', '', '', '', '', 'https://www.facebook.com/octaspace1');
