INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-54', '愛地球素食', '', '食', '澳門半島', '澳門鏡湖馬路139號新恒大廈地下A', 22.203563832552067, 113.54260970000001, '["食物"]', '🌱 愛地球｜不只是素食外賣，更是一種生活態度
每份餐點，都爲地球減少負擔，也爲身體注入能量
透過美味、便捷的素食選擇，輕鬆加入綠色飲食行列，一起守護環境與動物🐾
🍳 人氣小食：鐵板豆腐、鐵板小土豆、手打檸檬茶
🌿 多款優質菇菌、進口產品、冷凍素料，讓素食選擇更豐富、更安心
🥗 我們的使命是讓喫素變得簡單有趣
不用犧牲美味，也能愛地球！這裏總有一道料理，能驚豔你的味蕾✨', '', '星期一09:30 - 19:30
星期二至六10:00 - 20:00', '+853 6663 8499', '', 'published', '2026-11-10T06:37:16.508Z', '2026-11-10T06:37:16.508Z', '', '', '', '', 'https://www.facebook.com/p/%E6%84%9B%E5%9C%B0%E7%90%83%E7%B4%A0%E9%A3%9F-100069143713404/?locale=zh_CN');
