INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-58', 'Botanica綠茵亭', '', '食', '氹仔', '澳門銀河 嘉佩樂1樓', 22.147598, 113.553449, '["食物"]', '坐落於澳門銀河嘉佩樂的「綠茵亭」，宛如一方都市謐境。在此，酒店行政總廚Stephen Hsu以自然爲靈感之筆，創意重塑經典環球暖心菜餚，誠邀賓客入席，展開一段寧靜而深刻的感官巡禮。



這處以都市叢林爲靈感的空間，由Moinard Bétaille 操刀設計，僅設48席。光影交錯間，綠植與屏風巧妙區隔，既保持通透視野，又營造私密氛圍。墨西哥藝術家Joel Escalona 的紅橡木雕塑點綴其中，爲空間注入自然雅趣，完美映襯Stephen 主廚對風味與地域的細膩探索，營造出一處既令人沉浸又倍感親切的用餐之境。', '', '早餐：上午7時至下午2時（酒店住客專享）
午餐：中午12時至下午2時30分
下午茶：下午3時至5時30分
晚餐：晚上6時至10時', '電話+853 8883 2221', 'assets/catalog-8fca688f-6f44-5858-b353-5c9a3c05f5de.webp', 'published', '2026-11-10T06:37:16.504Z', '2026-11-10T06:37:16.504Z', '', '', '', '', 'https://www.galaxymacau.com/zh-hant/dining/restaurants/botanica/');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-62', 'O.N.E（本地純素皮具品牌）', '', '買', '澳門半島', '澳門聖祿杞街27號文昌大廈地下A座', 22.196695, 113.544324, '["減廢"]', 'ONE是一個設計師品牌，專注於生產純素皮革包和配飾，致力於打造對動物和地球友好的時尚產品。我們選用優質、耐用的純素皮革，並在可能的情況下，使用回收材料製作產品。', '', '星期一至日 中午1:00 至 晚上9:00', '+853 6268 6277', '', 'published', '2026-11-10T06:37:16.503Z', '2026-11-10T06:37:16.503Z', '', '', '', '', 'https://one-concepts.com/zh');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-63', '五月沐苔天然生活用品 (The Moss Natural L', '', '買', '澳門半島', '肥利喇亞美打大馬路（荷蘭園大馬路）60-60A號永明大廈BR/C', NULL, NULL, '["減廢"]', '澳門本土天然生活用品品牌，採用純天然植物萃取材料及可降解包裝，推出自備容器到店“裸買”洗潔精、天然洗衣粉、消毒及家居清潔用品的環保模式；同時自研手工皁、驅蚊膏、香薰蠟燭，定期開辦手作工作坊，並代售環保食物袋及環保月事用品', '', '週二至週日 12:00–21:00（週一休息）；時代工廈點：週一至週六 10:30–17:30', '+853 6240 8882', '', 'published', '2026-11-10T06:37:16.502Z', '2026-11-10T06:37:16.502Z', '', '', '', '', 'https://www.facebook.com/TheMoss.co');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-64', '米量雜貨店MaiLon Store', '', '買', '澳門半島', '樂建斜巷3號盈利大廈地鋪', 22.191948, 113.535887, '["減廢"]', '傑創立的澳門首間環保“裸買”雜貨店。「米量」拆自「糧」字，店內貨品全無塑膠包裝，顧客可自攜容器按需稱重購買白米、漢記手工麪餅、意大利粉、藜麥、果乾及無患子清潔品；店方亦備有街坊捐贈的玻璃瓶供免費重用', '', '週二至週六 11:00–19:30；週日及週一 14:00–19:30', '+853 6226 5000', '', 'published', '2026-11-10T06:37:16.501Z', '2026-11-10T06:37:16.501Z', '', '', '', '', 'https://www.facebook.com/MaiLonStore/');
