INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-75', '善明會“綠色技能小組” （玩具維修與縫補工作坊）', '', '修', '澳門半島', '馬場海邊馬路25號祐新大廈地下及一樓', 22.210349, 113.549677, '["減廢"]', '由善明會“陽光 Light up 義工團”主辦的免費綠色技能項目。邀請導師傳授玩具維修、布偶縫補、黏合修復及安全工具操作，幫助11歲或以上市民掌握延長舊玩具與毛絨公仔壽命的實用技術，並將修復成果回饋社區', '', '星期一至星期日，早上10時至晚上7時', '(853)2876 1805', '', 'published', '2026-11-10T06:37:16.493Z', '2026-11-10T06:37:16.493Z', '', '', '', '', 'https://sinmeng.org/');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-76', '澳門扶康會——寶利中心', '', '修', '澳門半島', '黑沙環馬場北大馬路寶利閣175-181號地下A', 22.214219, 113.552978, '["減廢"]', '中心業務包括：包裝、加工工作、郵件處理、手工藝製作、文創禮品、紀念品製作、陶瓷禮品、婚宴回禮、車縫、速印、派傳單等', '', '週一至週六 09:00–18:00', '2840 3988', '', 'published', '2026-11-10T06:37:16.492Z', '2026-11-10T06:37:16.492Z', '', '', '', '', 'https://www.fuhong.org.mo/pou_lei/index/index.html');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-77', '澳門扶康會——創藝工房', '', '修', '澳門半島', '十月初五日街135-A號新發大廈地下A座 / 黑沙環巷8號發利工業大廈6BB座', 22.196395, 113.537626, '["減廢"]', '藉由藝術創作令殘疾人士可以展現出創意，激發他們的潛能，同時亦可表達到自身的情感及抒發情緒。以表達性藝術治療為基礎，即使是同一媒介，在不同殘疾人士的創作上，皆能以不同的面貌呈現，因此每個藝術作品都是獨一無二的。通過由殘疾人士製作的藝術產品直接與市民接觸，讓產品作為宣傳及推廣的媒介，為社會注入殘疾人士對文創的支持和力量，同時亦可令大眾更瞭解殘疾人士，讓大眾能從藝術的角度，加深對他們在展能藝術上的認同和了解，從而建立出一個共融的社會。', '', '週一至週六 09:00–18:01', '2826 6036', '', 'published', '2026-11-10T06:37:16.491Z', '2026-11-10T06:37:16.491Z', '', '', '', '', 'https://www.fuhong.org.mo/creative_arts_house/index/index.html');
