INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-96', '龍環葡韻濕地生態區', '', '去', '氹仔', '氹仔海邊馬路及望德聖母灣大馬路北側 / 望德聖母灣街', 22.150696, 113.561504, '["自然與生物多樣性"]', '龍環葡韻濕地是澳門重要的生態區之一，區內設有生態步道及觀鳥屋，讓遊人可在免干擾生物棲息的情況下觀賞鳥類，感受綠意。除生態步道外，遊人也可遊覽附近的「龍環葡韻濕地科普園地」，園地設置昆蟲旅館等解說設施，展示生態共融概念，還有以濕地爲主題的戶外展覽，認識更多濕地的生態系統、動植物以及龍環葡韻濕地的變遷史，同時亦設有互動裝置及主題擺設，歡迎親子一同探索隱藏其中的有趣生物。', '', '龍環葡韻濕地科普園地：全天開放
西側生態池：逢週三、週六、週日、公眾假期及補假日，上午9時至下午5時
東側及北側生態步道：每日上午6時至下午6時（其餘步道全天開放）', '853) 2888 0087', 'assets/catalog-bf4ecc0a-d311-5165-8b8e-03edf53025b4.webp', 'published', '2026-11-10T06:37:16.475Z', '2026-11-10T06:37:16.475Z', '', '', '', '', 'https://www.macaotourism.gov.mo/zh-hant/events/whatson/9282');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-97', '路氹城生態保護區', '', '去', '氹仔', '路氹城蓮花大橋附近沿海及內陸濕地（與橫琴島隔水相望', 22.141286, 113.555402, '["自然與生物多樣性"]', '佔地約 55 公頃的重要紅樹林及淡水濕地保育區。設有自然研習徑、自然教室及觀鳥屋，綿延數公里的紅樹林是珍稀候鳥黑面琵鷺及各類鷺鳥的棲息地，定期舉辦免費公眾觀賞日', '', '半封閉式管理，按公眾觀賞日、生態區大步走或團體預約場次開放', '+853 2876 2626', '', 'published', '2026-11-10T06:37:16.474Z', '2026-11-10T06:37:16.474Z', '', '', '', '', 'https://apps.dspa.gov.mo/cepzweb/cenov_tc.aspx');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-98', '石排灣郊野公園', '', '去', '路環', '路環石排灣馬路', 22.126042, 113.55815, '["自然與生物多樣性"]', '佔地約 198,060 平方米的澳門最大自然動植物公園。園內的香徑藥谷生態園區、南藥園及石排灣濕地已全面開放免預約參觀，系統展示華南藥用植物、山地溪流與濕地生物多樣性', '', '郊野公園：每日 06:00–22:00；石排灣濕地、香徑藥谷及南藥園：每日 09:00–17:00（免預約自由進出）；大熊貓館：週二至日 10:00–13:00、14:00–17:00（週一休館）', '+853 2888 0087 / 2833 7676', 'assets/catalog-2724bfea-b017-5375-9ea4-44045a173387.webp', 'published', '2026-11-10T06:37:16.473Z', '2026-11-10T06:37:16.473Z', '', '', '', '', 'https://www.macaotourism.gov.mo/zh-hant/sightseeing/gardens/seac-pai-van-park');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-99', '九澳水庫淡水濕地', '', '去', '路環', '路環九澳堤壩馬路', 22.135073435414522, 113.57301537105728, '["自然與生物多樣性"]', '位於路環山谷與水庫區的受保護原生淡水濕地系統。爲保護脆弱的原生水源與生態環境，採取預約申請制開放', '', '按申請參觀時間開放（需預先向市政署辦理參觀申請）', '+853 2888 0087', 'assets/catalog-f938ded1-6ac8-5cf7-8734-d9b01fb8e712.webp', 'published', '2026-11-10T06:37:16.472Z', '2026-11-10T06:37:16.472Z', '', '', '', '', 'https://www.iam.gov.mo/c/naturearea/itemlist');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-100', '疊石谷濕地', '', '去', '路環', '路環高頂馬路', 22.12307688458806, 113.55935888106639, '["自然與生物多樣性"]', '位於路環山谷與水庫區的受保護原生淡水濕地系統。爲保護脆弱的原生水源與生態環境，採取預約申請制開放', '', '按申請參觀時間開放（需預先向市政署辦理參觀申請）', '+853 2888 0087', 'assets/catalog-5dd7f21e-8631-596d-b442-66610a2cdbcc.webp', 'published', '2026-11-10T06:37:16.471Z', '2026-11-10T06:37:16.471Z', '', '', '', '', 'https://www.iam.gov.mo/c/naturearea/itemlist');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-101', '澳門國際環保合作發展論壇及展覽 (MIECF)', 'MIECF', '去', '氹仔', '路氹城大型會展中心（項目經理機構位於澳門半島羅理基博士大馬路223-225號南光大廈8樓D室）', NULL, NULL, '["自然與生物多樣性"]', '自2008年起由澳門特區政府牽頭主辦的國際環保盛會。在“綠色公眾日”免費向市民展示最新環保科技、本澳環保基建模型及生態生活展板，並由澳門低碳發展協會等聯合頒發“環保展臺嘉許獎及綠色電費回贈', '', '每年定期舉辦', '+853 8798 9675', '', 'published', '2026-11-10T06:37:16.470Z', '2026-11-10T06:37:16.470Z', '', '', '', '', 'https://www.macaomiecf.com');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-102', '望廈山市政公園', '', '去', '澳門半島', '澳門望廈山', 22.208017, 113.547617, '["自然與生物多樣性"]', '望廈山原來是一片茂密的天然樹林，是澳門半島的“市肺”之一。九十年代修建成可供休閒活動的綠化空間，1997年開放並命名為望廈山市政公園。在公園原生的茂密植物叢中，還可以看到一些古舊的軍事設施。', '', '全日', '', 'assets/catalog-92f24ec1-6db5-55b6-854a-28c233c5f06a.webp', 'published', '2026-11-10T06:37:16.469Z', '2026-11-10T06:37:16.469Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=15a1c2d6-abd5-43f7-be67-781ac778dd50&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-103', '紀念碑花園', '', '去', '氹仔', '氹仔海洋花園大馬路', 22.157520562074314, 113.54248921493085, '["自然與生物多樣性"]', '花園於1991年建成，位於海洋花園大馬路，毗鄰澳門童軍總部和氹仔隧道；此園依山而建，小而雅緻，其內豎立了一個紀念葡萄牙戰船「第二瑪麗亞」號爆炸事件中罹難人士之紀念碑，花園由此得名。', '', '全日', '2833 7676', 'assets/catalog-7fc383e6-39d0-5bfb-92fd-c9471f969e3c.webp', 'published', '2026-11-10T06:37:16.468Z', '2026-11-10T06:37:16.468Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=cd3ab314-1626-4378-992b-3a69cc66f7e3&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-104', '馬交石炮台公園', '', '去', '澳門半島', '澳門馬交石炮台馬路及馬交石炮台斜坡', 22.20334995644695, 113.55544266955019, '["自然與生物多樣性"]', '馬交石炮台公園依馬交石山的山坡就勢而建，主要以石級、涼亭、迴廊及平台等建築構建，跨越小山兩邊及連接到位於山頂的馬交石炮台。馬交石炮台又名瑪利亞二世皇后炮台，約建於1851至1852年間，為輔助望廈炮台以鞏固東北邊防功能。二戰期間，炮台遭美軍戰機炸毀，直至附近通訊博物館建成，才一併修復。公園可眺望到澳門東端水塘、新口岸一帶及海角遊雲的風景，是景色怡人的觀光好去處。', '', '全日', '2834 7676', 'assets/catalog-d3ec6e92-6b71-5b33-b302-c135032efaa1.webp', 'published', '2026-11-10T06:37:16.467Z', '2026-11-10T06:37:16.467Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=3ca3a344-c357-4415-a6f9-4f568e381149&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-105', '紀念孫中山市政公園', '', '去', '澳門半島', '澳門何賢紳士大馬路', 22.216142, 113.54501, '["自然與生物多樣性"]', '原址於1983年之前是鴨湧河垃圾堆填區，該公園是澳門北區最多人使用的公園之一，亦是本澳最先進行環保試點的產物。揉合了中西園林的特色。由於垃圾堆填高低不平的關係，整座公園亦按照地形以寬闊的波浪形草坪為設計基礎。園內設施多，包括有足球場、羽毛球場、圖書館、泳池、燒烤區、表演場、兒童遊樂場以及成人設施區等等。', '', '全日', '2835 7676', 'assets/catalog-ec2bfa5b-2955-5d5e-9c6c-113fd10a7c8a.webp', 'published', '2026-11-10T06:37:16.466Z', '2026-11-10T06:37:16.466Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=af04d73a-0ff1-40b6-9960-8c9223750028&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-106', '氹仔中央公園', '', '去', '氹仔', '氹仔成都街 7號', 22.159467, 113.554092, '["自然與生物多樣性"]', '氹仔中央公園總面積為23,220平方米，綠化面積為12,866平方米，植物品種多樣，超過40個種類。公園綠化最大特色是位於公園兩端的土丘上種植了數十株的櫻花樹，未來或許能夠成為澳門市民賞櫻園。此外，園內種植了賞果的鐵冬青、賞花的宮粉羊蹄甲、大葉紫薇及藍花楹等，營造出四季繽紛的花園。', '', '週一至週日06:00 - 24:00', '2836 7676', 'assets/catalog-e6c4a1c3-aa4c-5b4b-bccb-b3d36915b9ab.webp', 'published', '2026-11-10T06:37:16.465Z', '2026-11-10T06:37:16.465Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=5571ff2b-219d-4978-a15a-ad5daa43ee5e&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-107', '花城公園', '', '去', '氹仔', '氹仔埃武拉街', 22.156416, 113.557075, '["自然與生物多樣性"]', '這座是離島唯一採用中國園林式庭園建築的公園，所謂‘麻雀雖小，五臟俱全’，花城公園可以說功能齊全，植物多樣，每年4-9月，可在池塘中觀賞荷花，在池塘的周圍還建有小橋、假山石景、百花亭和長廊等，加上小型盆景的擺設，更添公園中式古典園林的韻味，使公園仿如石屎森林中的世外桃源。設於正門的大型九龍石壁，是花城公園的重要景點，令整個公園倍添高雅。', '', '週一至週日06:00 - 24:00', '2837 7676', 'assets/catalog-57f2ee3b-b402-52eb-a5bd-dcfafedecc96.webp', 'published', '2026-11-10T06:37:16.464Z', '2026-11-10T06:37:16.464Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=de83b188-49e1-4508-90c4-592411532a7b&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-108', '九澳高頂燒烤公園', '', '去', '路環', '九澳高頂馬路末段', 22.129142629974584, 113.57536578903218, '["自然與生物多樣性"]', '位於九澳高頂馬路末段，離路環東北步行徑入口不遠。面積約2,788平方米。園內設有停車場及公共電話亭。備有一般燒烤的設施及別具特色的戶外野餐桌椅。由於靠近公路旁，容易到達，甚受市民歡迎。', '', '全日', '2838 7676', 'assets/catalog-3a5037a1-e99d-5b0f-be4d-961f4e0077f8.webp', 'published', '2026-11-10T06:37:16.463Z', '2026-11-10T06:37:16.463Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=d731b1bb-8dff-4b0f-87f5-1c1e3f80f43c&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-109', '竹灣燒烤公園', '', '去', '路環', '路環竹灣馬路', 22.1143520160153, 113.56283987152577, '["自然與生物多樣性"]', '園內建有集水池和花槽，終年山水不斷，樹木婆娑、環境幽靜，每每三五知己相約到此燒烤，在海風和夜靜的環境下，特別容易觸動人心。園外馬路對面有一道長石階可直抵竹灣海灘。公園後方則有一條長長的麻石階，貫穿環繞園內兩條一高一低的小徑，沿此石階拾級而上可到達全澳最長的路環步行徑，所以無論想燒烤、游泳或郊遊都十分方便，為假日活動增添不少樂趣。', '', '全日', '2839 7676', 'assets/catalog-bbf72031-23f8-5096-8bd3-9af28d0d4b94.webp', 'published', '2026-11-10T06:37:16.462Z', '2026-11-10T06:37:16.462Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=754b1fde-d71a-41e5-9b1d-0df438d8ad85&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-110', '恩尼斯花園', '', '去', '路環', '路環市中心', 22.118001, 113.551818, '["自然與生物多樣性"]', '位於路環市中心，面積680平方米，居民喜歡稱之為「花園仔」，園內長有一棵巨大的龍眼樹，綠葉成蔭，路環的居民最喜歡聚於此地休息聊天。', '', '全日', '2840 7676', 'assets/catalog-214cde38-79ab-59db-8581-f758e289d89d.webp', 'published', '2026-11-10T06:37:16.461Z', '2026-11-10T06:37:16.461Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=e48b295d-19ee-4dda-9192-269a0219560f&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-111', '市政署大樓內庭花園', '', '去', '澳門半島', '澳門新馬路163號市政署大樓', 22.19318029168093, 113.53940496976733, '["自然與生物多樣性"]', '市政署大樓內庭花園的大門兩側向花園延伸的牆身飾有傳統葡式瓷磚，以藍白色為主調，與中國的青花瓷十分相似。園內後方豎立着兩個石球，一個刻有葡萄牙盾徽，另一個刻有渾天儀圖案，象徵着葡萄牙對地理大發現所作出的重大貢獻及其偉大的航海事業和探險精神。', '', '週一至週日09:00 - 21:00', '2841 7676', 'assets/catalog-ff50619c-1432-58b9-bc35-b26f6f1e48b3.webp', 'published', '2026-11-10T06:37:16.460Z', '2026-11-10T06:37:16.460Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=2d78ed26-09fd-448b-977b-ece8525a06c3&type=gardenn');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-112', '市政狗房花園', '', '去', '澳門半島', '澳門提督馬路', 22.207418, 113.546099, '["自然與生物多樣性"]', '市政狗房花園與市政狗房相鄰，園內擺設了一座傳播愛護動物訊息的雕塑。此園採用開放式花園設計，以綠化景觀為主體，面積雖然不大，但栽種了不同類別的植物供遊人觀賞。', '', '全日', '2842 7676', 'assets/catalog-faba54c3-4fff-56a2-b1a2-209a9d1a0c5d.webp', 'published', '2026-11-10T06:37:16.459Z', '2026-11-10T06:37:16.459Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=e813b005-c6fd-4575-b4c2-e7358c316816&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-113', '西望洋花園', '', '去', '澳門半島', '澳門西望洋馬路', 22.184843, 113.533445, '["自然與生物多樣性"]', '西望洋花園位處西望洋山西望洋馬路，公園及周邊環境建築物優美寧靜，綠樹成蔭空氣好，內設兒童遊樂設施、健身設施、羽毛球場、綜合球場等，是休閑娛樂和鍛煉身體的好地方。', '', '全日', '2843 7676', 'assets/catalog-1d3aea69-8e10-5903-aab3-512641dfeb6a.webp', 'published', '2026-11-10T06:37:16.458Z', '2026-11-10T06:37:16.458Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=cdae9ab5-8225-4d50-867e-cf5601826a71&type=gardenn');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-114', '望德樓平台花園', '', '去', '澳門半島', '慕拉士大馬路望廈社屋-望德樓二樓', 22.20682044307716, 113.55130523443223, '["自然與生物多樣性"]', '市政署一直持續優化各區市民的綠化休憩空間，位於慕拉士大馬路望廈社屋-望德樓二樓的望德樓平台花園於2022年8月15日對外開放使用，園內設有多項大眾設施，包括兒童遊樂設施、健身設施、公共洗手間、涼亭、休閒長椅及可供下棋的桌椅等，為市民提供一個休閒活動的好去處。', '', '週一至週日08:00-22:00', '2844 7676', 'assets/catalog-1037ca47-3b0d-5ed0-a3cb-21fe2d6be191.webp', 'published', '2026-11-10T06:37:16.457Z', '2026-11-10T06:37:16.457Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=9e2f6475-8761-4434-90d8-3ad67cbe280e&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-115', '何賢公園', '', '去', '澳門半島', '澳門宋玉生廣場', 22.192074, 113.549387, '["自然與生物多樣性"]', '何賢公園，又名「香山公園」。於1993年落成，為紀念澳門華人領袖何賢紳士而建。「何賢公園」與「宋玉生公園」首尾相接，形成一道長方形的綠色走廊，設計簡單明朗，設施豐富多元化，整體富現代感。', '', '全日', '2845 7676', 'assets/catalog-94566649-b599-51fe-aa5e-f5151e9d173e.webp', 'published', '2026-11-10T06:37:16.456Z', '2026-11-10T06:37:16.456Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=8fa18c3d-240c-41cf-8c76-2a968ce58347&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-116', '水塘公園', '', '去', '澳門半島', '澳門水塘周邊', 22.199389, 113.55494, '["自然與生物多樣性"]', '水塘公園於2000年伴隨水塘馬路工程一起動工，分兩期建成環繞水塘全長約2600米，集康體設施和綠化休憩的公園，也是連接新口岸與黑沙環的重要步行通道。', '', '全日', '2846 7676', 'assets/catalog-392079da-05e2-53bf-b899-15271fa82c05.webp', 'published', '2026-11-10T06:37:16.455Z', '2026-11-10T06:37:16.455Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=dd7a29cf-853c-4777-8881-bf8da2df76f3&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-117', '螺絲山公園', '', '去', '澳門半島', '澳門新雅馬路 / 亞馬喇馬路', 22.204402, 113.5523, '["自然與生物多樣性"]', '螺絲山面積雖小，但這裡有很多鄉土的樹種，如樸樹、潺槁樹、山蒲桃、白車、山石榴、布渣葉等。其中林沿種有數棵假蘋婆，每年夏秋結果期，鮮紅色的果殼內綴上黑色的種子掛滿樹梢，構成螺絲山特有的景觀。', '', '週一至週日06:00-24:00', '2847 7676', 'assets/catalog-bccfc744-db30-5dbf-a0f8-17d4e6b1b6c8.webp', 'published', '2026-11-10T06:37:16.454Z', '2026-11-10T06:37:16.454Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=0c81ad6a-f224-4322-8986-7128325081b4&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-118', '白鴿巢公園', '', '去', '澳門半島', '澳門白鴿巢前地', 22.19972, 113.53951, '["自然與生物多樣性"]', '公園曾作為東印度公司收集植物用的苗圃，留存多種古樹，是古樹種類較多的綠地。古樹樹種有假菩提樹、假柿木薑子、海南蒲桃、翻白葉樹、羅漢松、榕樹等。正門廣場的一株麵包樹為本澳第一株母株。', '', '週一至週日06:00-24:00', '2848 7676', 'assets/catalog-160f4b46-3aa9-55e1-b651-19273ed8869c.webp', 'published', '2026-11-10T06:37:16.453Z', '2026-11-10T06:37:16.453Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=a048da4e-ade7-40b2-af99-e704f0dce95b&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-119', '路環山頂公園', '', '去', '路環', '路環高頂馬路上方', 22.1223702848793, 113.56397141879926, '["自然與生物多樣性"]', '沿路環高頂馬路直上，就可到達路環山頂公園，距路環最高點（海拔170.6米）只200米左右。從該公園遠眺，視野特別廣闊，觸目所及正是優美的黑沙海灘及黑沙村。園內一片綠茵，並有多種兒童遊樂設施，加上空氣清新，令人心曠神怡，是假日消閒野餐之理想場所。', '', '全日', '2849 7676', 'assets/catalog-62aaca33-8276-5d8f-bbfb-b028a19ce910.webp', 'published', '2026-11-10T06:37:16.452Z', '2026-11-10T06:37:16.452Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=a8f21fdf-bf38-4c0b-8e03-f6d7e98149af&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-120', '松山市政公園', '', '去', '澳門半島', '澳門東望洋山', 22.198501, 113.552198, '["自然與生物多樣性"]', '松山市政公園是以澳門半島最高的東望洋山為主體，並配合附近的環境和設施所組成的一個多功能公園，在這裡可以從最廣闊和最美的角度眺望澳門市區及離島。', '', '全日', '2850 7676', 'assets/catalog-a6709ae7-b1d3-5d9e-ae11-8c0c51a8afd9.webp', 'published', '2026-11-10T06:37:16.451Z', '2026-11-10T06:37:16.451Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=e136628b-5c7e-444f-9d17-5256211020ff&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-121', '棕櫚公園', '', '去', '路環', '路環棕櫚圓形地', 22.127425652505824, 113.55686813592912, '["自然與生物多樣性"]', '園內設有公共洗手盆、景觀噴水池、兒童遊戲區、小型迷宮、休閒涼亭等設施。園外一側亦設有以金屬圍欄獨立圍封的遛狗區。園內環境優美，適合一家大小休閒活動。', '', '週一至週日06:00-24:00', '2851 7676', 'assets/catalog-e0cabd69-0d61-5eb8-bd87-9958cd6c8aea.webp', 'published', '2026-11-10T06:37:16.450Z', '2026-11-10T06:37:16.450Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=884347ef-0889-4744-8124-d0da1e0a0bd9&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-122', '石排灣市區公園', '', '去', '路環', '石排灣水庫周邊', 22.132032880133746, 113.56569570474375, '["自然與生物多樣性"]', '石排灣市區公園於2021年10月下旬啟用，公園24小時全日開放。園內設有兒童遊樂場、單車徑、跑步徑、步行徑、康體區及洗手間等，是一個運動及育樂設施兼具的公園，適合一家大小的消閒好去處。', '', '全日', '2852 7676', 'assets/catalog-6f3c05fd-412d-531a-90d2-d6134673dd29.webp', 'published', '2026-11-10T06:37:16.449Z', '2026-11-10T06:37:16.449Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=c61d0bff-460e-4b39-afda-8b78e62eb88f&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-123', '大炮台公園', '', '去', '澳門半島', '澳門博物館前地', 22.196835, 113.541952, '["自然與生物多樣性"]', '大炮台公園在澳門著名景點大炮台和大三巴之間，公園近大三巴入口的步行徑是遊客拍攝大三巴牌坊的熱門位置，並設有健身設施讓市民做運動，沿石級登上上層步行徑更可以環繞大炮台從高處俯瞰周圍美景，是遊客及市民欣賞風景散步的好去處。', '', '全日', '2853 7676', 'assets/catalog-d746a26b-24c1-5745-9649-e5b29fc9454f.webp', 'published', '2026-11-10T06:37:16.448Z', '2026-11-10T06:37:16.448Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=17d8b490-34e1-445b-88e0-87e4ba2cd25e&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-124', '湖畔大廈平台花園', '', '去', '氹仔', '氹仔美副將馬路', 22.159075, 113.561254, '["自然與生物多樣性"]', '園內設有多項大眾設施，包括兒童遊戲設施、健身設施、涼亭，其內皆設有休閒長椅及可下棋的野餐桌椅、羽毛球自由波地等等，讓市民各取所需。', '', '週一至週日08:00-22:00', '2854 7676', 'assets/catalog-0ee77849-e757-5a74-bbc9-cf3d09c0f272.webp', 'published', '2026-11-10T06:37:16.447Z', '2026-11-10T06:37:16.447Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=513fdff2-4231-4af3-ab22-5193f8c32b08&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-125', '燒灰爐公園', '', '去', '澳門半島', '澳門西灣街', 22.186775, 113.537255, '["自然與生物多樣性"]', '燒灰爐公園雖然面積細小，但除了一般設施如公廁、卵石徑、休憩桌椅及兒童遊樂場外，還設有兒童電動車場', '', '週一至週日06:00-24:00', '2855 7676', 'assets/catalog-1fe76930-10ff-5b24-a366-487f695520f7.webp', 'published', '2026-11-10T06:37:16.446Z', '2026-11-10T06:37:16.446Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=2330bbbf-a08d-4215-b4bf-a71be8a4ba2f&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-126', '得勝花園', '', '去', '澳門半島', '澳門士多鳥拜斯大馬路', 22.19866902994273, 113.54874337254306, '["自然與生物多樣性"]', '得勝花園是將“得勝前地 ”重整後建成的。這個廣場呈圓形，直徑58米，位於昔日華士古打監麻新路北面，其中間路段繞過這廣場。', '', '全日', '2856 7676', 'assets/catalog-91599f9a-abd7-58c1-b64e-faabbb863ad2.webp', 'published', '2026-11-10T06:37:16.445Z', '2026-11-10T06:37:16.445Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=2a7b9135-3050-4d92-8181-63e41a94f642&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-127', '二龍喉公園', '', '去', '澳門半島', '澳門士多鳥拜斯大馬路', 22.200667, 113.551394, '["自然與生物多樣性"]', '十九世紀期間的澳督羅沙(Tomas de Sousa e Rosa)在任時，這裡被選作樹苗場栽培植物，作為美化松山崗陵和城市街道之用，以及移植到新闢的花園內，當時曾經被稱為植物園。從公園正門直入可見一條康莊大道，兩旁種植不同品種的喬木和灌木，在林蔭大道的終端，建有一座小型池塘，池塘四周，迴廊輕繞，『魚泉』相伴。拾級而上，可直達松山市政公園。', '', '全日', '2857 7676', 'assets/catalog-0ae4d4c2-593f-5e27-9721-dae1d0e4fe28.webp', 'published', '2026-11-10T06:37:16.444Z', '2026-11-10T06:37:16.444Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=c0a9fc3c-dadc-487a-bc5e-913abf5e5709&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-128', '路環兒童公園', '', '去', '路環', '路環十月初五馬路', 22.11501947431457, 113.55064838935442, '["自然與生物多樣性"]', '位於路環十月初五馬路，園內設有兒童遊樂設施，環境幽靜，空氣清新，是一家大小的消閒的好去處。', '', '全日', '2858 7676', 'assets/catalog-ddc2fd64-f9f4-584b-96bc-8d0835d85e66.webp', 'published', '2026-11-10T06:37:16.443Z', '2026-11-10T06:37:16.443Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=a35921d3-6767-42d0-8c4e-3706c806750f&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-129', '華士古達嘉馬花園', '', '去', '澳門半島', '澳門東望洋街', 22.196311, 113.546571, '["自然與生物多樣性"]', '1997年花園大肆重整，在園內下方增建波浪形噴水池，修築無障礙路徑；在公園上方，環繞銅像修建了水池和噴泉。兒童遊樂場也重整，搭建涼亭，供市民歇息，增設多項遊樂設施，這處是受歡迎的兒童遊樂場之一。', '', '全日', '2859 7676', 'assets/catalog-05a34a46-9f79-5c9e-9ab5-4bcd3841dc3f.webp', 'published', '2026-11-10T06:37:16.442Z', '2026-11-10T06:37:16.442Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=d342bf3e-4a94-423a-a465-35e5b5b66229&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-130', '盧廉若公園', '', '去', '澳門半島', '澳門羅利老馬路10號', 22.20074752420758, 113.54794016489929, '["自然與生物多樣性"]', '澳門半島唯一蘇杭園林設計風格的名園，園內處處亭臺樓閣，池塘橋榭，洞臺飛瀑，奇石異巖，曲徑迴廊，展現蘇杭園林的最大特色。同時，園內仍融合了南歐特色建築，如春草堂、圍牆等，體現中西文化交融的澳門文化。', '', '週一至週日06:00-24:00', '2860 7676', 'assets/catalog-f17cd974-4a39-5e53-b762-ef126d707f71.webp', 'published', '2026-11-10T06:37:16.441Z', '2026-11-10T06:37:16.441Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=e9cfbdb8-2cb8-4e60-99eb-5c35ddb459b1&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-131', '黑沙環三角花園', '', '去', '澳門半島', '澳門拱形馬路', 22.210456, 113.548416, '["自然與生物多樣性"]', '黑沙環三角花園由拱形馬路、黑沙環馬路及關閘馬路包圍著的小型開放式公園，呈三角形。公園中央設有一座藍色琉璃瓦頂的涼亭，配有卵石徑、健身設施、棋枱及廁所。而且這公園位於人口密集的社區，成為附近眾多中老年居民下棋會友、自娛自樂等活動的聚集地。', '', '全日', '2861 7676', 'assets/catalog-93cb212b-cbcc-58b8-92f4-30e998bb19bb.webp', 'published', '2026-11-10T06:37:16.440Z', '2026-11-10T06:37:16.440Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=c148fa3f-2a9d-4b90-a617-8aa2858cb0f8&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-132', '宋玉生公園', '', '去', '澳門半島', '澳門宋玉生廣場', 22.189203, 113.550718, '["自然與生物多樣性"]', '宋玉生公園的設計如一條林蔭大道，沿路舖砌葡式碎石，兩旁種植巴西鳶尾等陰生植物；北面設有兒童遊樂場及健身設施區，林蔭大道兩旁設有覆蓋了炮仗花和紫藤的涼亭、休憩區以及休息椅；公園兩邊種植多種喬木及灌木，南面還有池塘和小橋，遊人可享受休憩設施，亦可遠眺海', '', '全日', '2862 7676', 'assets/catalog-45c27df9-04d8-5fe3-aa81-11f5fa8539ab.webp', 'published', '2026-11-10T06:37:16.439Z', '2026-11-10T06:37:16.439Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=0c57fc6f-f356-46cd-9cd4-cb926c468d57&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-133', '黑沙海灘公園', '', '去', '路環', '澳門黑沙海灘', 22.121814, 113.570213, '["自然與生物多樣性"]', '黑沙海灘公園是一個適宜全家大小共度週末假日的好地方。黑沙海灘之所以得名，是因為它的沙全都是黑色的，是鄰近地區較具特色的海灘。近年因流失大量黑沙，因此澳門當局不得不進行人工造灘，添加大量的黃沙，所以黑沙海灘現在看起來已不如從前的黑色一片，但只要用手去大力得挖一下，黃沙的底部仍然是黑沙，原因是黑沙的體積遠小於黃沙。所以各位要好好珍惜這個海灘，因為自然資源得來不易。', '', '全日', '2863 7676', 'assets/catalog-40625426-ef72-518a-87c7-d0b5f608c48d.webp', 'published', '2026-11-10T06:37:16.438Z', '2026-11-10T06:37:16.438Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=b36389d7-51df-425d-9b7a-dfcb5bc5dd2f&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-134', '黑沙環公園', '', '去', '澳門半島', '澳門勞動節大馬路與馬場東大馬路', 22.210893, 113.55406, '["自然與生物多樣性"]', '公園內設有四個兒童遊戲區及三個綜合運動場，分佈在園內各區。此外，園內的長廊、花架、以及蔭棚設計新穎。黑沙環公園是澳門繁華市區中較大型的公園，且設施齊備，為周邊居民提供多方面的休閒娛樂。', '', '全日', '2864 7676', 'assets/catalog-4b6569cf-b9ae-5859-9865-0037f4c06d05.webp', 'published', '2026-11-10T06:37:16.437Z', '2026-11-10T06:37:16.437Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=2b36b377-6864-40d3-b99b-9d1a5dfd9f6c&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-135', '祐漢街市公園', '', '去', '澳門半島', '澳門市場街', 22.211151, 113.552091, '["自然與生物多樣性"]', '祐漢街市公園，因公園與祐漢街市互相緊密相連，故名為祐漢街市公園。於1994年建成啓用，公園為一個全日開放式的廣場設計，坐落於澳門人口密度較高的北區，鄰近有一座大型的祐漢市政綜合大樓。', '', '全日', '2865 7676', 'assets/catalog-299eb494-fc5b-55a8-86e5-c5706086e0d4.webp', 'published', '2026-11-10T06:37:16.436Z', '2026-11-10T06:37:16.436Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=8622c560-87ad-4ba7-8c68-73da45c61871&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-136', '碼頭花園', '', '去', '氹仔', '氹仔柯維納馬路旁', 22.156704, 113.542172, '["自然與生物多樣性"]', '園內植物種類繁多，花團錦簇，草本、時花、灌木、喬木和藤本一應俱存。每到夏季蔭棚上已開滿使君子，與園中央有一株碩大的鳳凰木及紫微等，為該區的初夏帶來一場花的盛宴。', '', '全日', '2866 7676', 'assets/catalog-ef893107-250e-59d4-9e0f-340c33271e09.webp', 'published', '2026-11-10T06:37:16.435Z', '2026-11-10T06:37:16.435Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=a71cb45f-ad93-4993-8233-485855871f07&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-137', '黑沙公園', '', '去', '路環', '路環新黑沙馬路', 22.118125262760127, 113.56898903846742, '["自然與生物多樣性"]', '黑沙公園的名稱由來是由於位處黑沙海灘，此公園主要是以康體設施為主，分別有游泳池、小型足球場、籃球場、羽毛球場、網球場、乒乓球枱及多款成人健身設施，如果你是一個運動發燒友，這個公園的運動設施足夠您玩上一整天；另外還有提供給小朋友玩的兒童遊戲設施區、野餐區及一大片綠油油的草坪，是一家大小消閒的好去處。', '', '週一至週日06:00-24:00', '2867 7676', 'assets/catalog-0d8dfab9-f19d-5d09-af00-4f4456c5c9ec.webp', 'published', '2026-11-10T06:37:16.434Z', '2026-11-10T06:37:16.434Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=3119e6e4-f703-430a-9fc5-4a1914110ff1&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-138', '加思欄花園(南灣花園)', '', '去', '澳門半島', '澳門南灣大馬路東望洋新街', 22.192526, 113.544608, '["自然與生物多樣性"]', '歷史悠久，是澳門的首座花園，原址是卡斯蒂利亞(西班牙)方濟各會會士於1580年2月2日建立的聖方濟各修道院，其中文名的意思就是“卡斯蒂利亞人的花園”。西班牙方濟各會會士後來由葡國方濟各會會士取代，1834年，由於葡國宗教團體被取締，因此前澳門政府亦接管了他們的土地和財產。', '', '全日', '2868 7676', 'assets/catalog-c409b4c2-6909-5883-802f-a295ae131b2e.webp', 'published', '2026-11-10T06:37:16.433Z', '2026-11-10T06:37:16.433Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=177268cc-a435-4fcb-ace6-34309b6d8d3a&type=gardenn');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-139', '黑沙環海濱公園', '', '去', '澳門半島', '澳門友誼橋大馬路海濱', 22.208961, 113.560921, '["自然與生物多樣性"]', '公園位於友誼橋大馬路旁的一個長帶狀開放式的綠化休憩空間，全長約1,000公尺，闊15至20公尺。公園沿海岸線種植了樹木，鋪設草坪和設置長椅，遊人可以在此欣賞海景，亦可沿堤岸散步、漫跑和休憩。園內有小型露天廣場，不少居民都喜在此聚會，享受閒適。位於公園中央部分對面是由羅若誠(Jose Rodrigues)設計的“東方明珠紀念碑”，大大小小共8顆的“明珠”在噴泉中“升起”，在燈光的拱照下，明亮迷人。', '', '全日', '2869 7676', 'assets/catalog-3d22ff59-699f-5437-a215-1b0b31d7e475.webp', 'published', '2026-11-10T06:37:16.432Z', '2026-11-10T06:37:16.432Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=047f8ef5-083c-49fc-bd1d-5e93adca9922&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-140', '石排灣社區綜合大樓天台花園', '', '去', '路環', '路環蝴蝶谷大馬路', 22.128676, 113.561837, '["自然與生物多樣性"]', '石排灣社區綜合大樓天台花園​位於蝴蝶谷大馬路石排灣社區綜合大樓7樓天台，具有多項休憩康體設施，包括兒童遊樂區、健身設施，現場亦設置綠化蔭棚，為市民提供健身及休閒空間。', '', '週一至週日06:00-22:00', '2870 7676', 'assets/catalog-f417b324-78a5-559f-bf39-f63e029be0d9.webp', 'published', '2026-11-10T06:37:16.431Z', '2026-11-10T06:37:16.431Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=6846567d-e60c-407b-925e-a44f44105083&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-141', '氹仔市政花園', '', '去', '氹仔', '氹仔嘉路士米耶馬路', 22.154231, 113.559438, '["自然與生物多樣性"]', '氹仔市政花園於1924年落成。位於氹仔嘉路士米耶馬路嘉模聖堂的前方，位於婚姻登記局與嘉模泳池之間。花園最大特色的地方是園中同期建成的小噴泉及其蔭棚，水池形狀呈一個十字型的花瓣，十分獨特，現今還在運作中，圓形蔭棚上種植了花多色艷的藤本植物如金銀花；另外就是豎立在最高處的一尊葡國著名詩人賈梅士的雕像，值得一看。', '', '全日', '2871 7676', 'assets/catalog-34a6d4ca-3215-5a75-adf2-1abc59efc8f4.webp', 'published', '2026-11-10T06:37:16.430Z', '2026-11-10T06:37:16.430Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=0dc71b80-1aab-47b1-9f58-eab9ad765a69&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-142', '藝園', '', '去', '澳門半島', '澳門友誼大馬路', 22.190582, 113.54894, '["自然與生物多樣性"]', '藝園於1999年12月9日開幕，公園原址是一條明渠，後來因衛生環境關係改建為暗渠，園內除廣植樹木和設有兒童遊戲設施外，其特色是園內各處設置了多個大型藝術雕塑及澳門名人塑像，成為青翠宜人和多功能的開放式公園。', '', '全日', '2872 7676', 'assets/catalog-490f0377-1fb9-54ef-a60f-52aa13820af5.webp', 'published', '2026-11-10T06:37:16.429Z', '2026-11-10T06:37:16.429Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=1e1dde44-a33f-466d-958f-196c8bfbf21d&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-143', '史劉蓮德博士眺望台（十字花園）', '', '去', '氹仔', '氹仔嘉路士米耶馬路', 22.153373565665948, 113.55904075447928, '["自然與生物多樣性"]', '整個花園沿斜坡呈梯形設置，樹槽、路沿護圍欄均以海浪形設計，園內建築以白色、紅色和粉綠色為主色，充分體現昔日澳葡的海洋文化，將海洋帶入園林景觀之中。過去四、五十年代的史劉蓮德博士眺望台直接接壤海邊，所以花槽的設計是呈波浪形', '', '全日', '2873 7676', 'assets/catalog-46fdb38c-9c54-53a0-91ae-ac53c1518caa.webp', 'published', '2026-11-10T06:37:16.428Z', '2026-11-10T06:37:16.428Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=210d079a-8269-4ff7-a94c-3bf768ab4456&type=garden');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-144', '大潭山郊野公園', '', '去', '氹仔', '氹仔天文臺斜路', 22.159079, 113.570652, '["自然與生物多樣性"]', '大潭山郊野公園位於氹仔東面，範圍包括雞頸馬路、嘉樂庇總督馬路和司徒澤雄神父馬路之間大片的山林地帶。設有眺望台、觀景亭、兒童遊樂區、燒烤區、人造草滑草場、步行徑、茶花園，集休憩、健身、環保、教育及陶冶性情等多重功能，是市民享受森林浴，回歸大自然，豐富休閒生活的好去處。', '', '全日', '2874 7676', 'assets/catalog-3d023b76-7a6f-546a-89c9-8e5cc2778ac8.webp', 'published', '2026-11-10T06:37:16.427Z', '2026-11-10T06:37:16.427Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=44ca23c2-4486-4eb5-802d-4490ca890d42&type=park');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-145', '黑沙水庫郊野公園', '', '去', '路環', '路環黑沙馬路', 22.124216, 113.571102, '["自然與生物多樣性"]', '黑沙水庫郊野公園位於路環島中央山以東南的山林地帶，範圍東至鷺環海天度假酒店入口的黑沙馬路，南至萬康園對面的「豬牯塘」出水口，總面積約37.1公頃。從地形上來說，公園內以黑沙水庫最具特色，故郊野公園亦以黑沙水庫命名。', '', '全日', '2875 7676', 'assets/catalog-4aa657f5-dc70-5de8-b6c9-21815abda04b.webp', 'published', '2026-11-10T06:37:16.426Z', '2026-11-10T06:37:16.426Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=9bdd239f-a241-4c95-b9bc-6a0f3e4de1a0&type=park');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-146', '九澳水庫郊野公園', '', '去', '路環', '九澳堤壩馬路', 22.133846, 113.577967, '["自然與生物多樣性"]', '郊野公園以九澳水庫為中心，周邊配套有的東北步行徑系統和九澳水庫環湖徑、小春溪、燒烤區、野餐區、戶外體驗營和淡水濕地生態區等', '', '全日', '2876 7676', 'assets/catalog-81b14282-9326-5c4d-8ca1-8b2745246d7e.webp', 'published', '2026-11-10T06:37:16.425Z', '2026-11-10T06:37:16.425Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/park/detail?id=b56647c1-41b2-4bf0-b05b-e6cbeec9f29e&type=park');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-147', '石排灣濕地', '', '去', '路環', '石排灣郊野公園', 22.126589644489744, 113.56123936485793, '["自然與生物多樣性"]', '位於石排灣郊野公園東北角，鄰近澳門原有山澗的一片區域，原為只有大片芒萁生長，且受到藤蔓及外來入侵植物嚴重覆蓋的區域，生態功能低，無法吸引動物棲息停留，市政署透過對區內的水體進行改善、規劃濕地動線鋪設、安裝休憩平台涼亭等設施，以循序漸進方法進行引水和養水，種植原生植物吸引各種動物和昆蟲，經過多年努力，區內漸漸形成濕地生境。', '', '每日09:00-17:00內進出參觀', '', 'assets/catalog-584f43ac-cc7c-5f60-b27b-8c807fceb1d1.webp', 'published', '2026-11-10T06:37:16.424Z', '2026-11-10T06:37:16.424Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/nature/detail?id=f05b655c-22fe-4226-9dc4-1da667fe12fc&type=naturearea');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-148', '香徑藥谷生態園區及南藥園', '', '去', '路環', '石排灣郊野公園', 22.123356, 113.558818, '["自然與生物多樣性"]', '香徑藥谷生態園區及南藥園位於路環石排灣郊野公園，擁有豐富的天然山水資源，依傍着的疊石塘山亦是本澳生物多樣性最豐富的地區。在保留其原有生境特性及原生植物的前題下，透過引入多樣化的藥用植物，同時牽引原生動物及昆蟲，成為澳門自然生態保護及溪谷生態保育的重要場所。', '', '每日09:00-17:00內進出參觀', '', 'assets/catalog-e57f6f02-94c2-58e9-a4aa-6e7e53e3d5cf.webp', 'published', '2026-11-10T06:37:16.423Z', '2026-11-10T06:37:16.423Z', '', '', '', '', 'https://www.iam.gov.mo/nature/c/facility/nature/detail?id=8b9fe1c4-3d37-45bc-b91c-2265bacf236b&type=naturearea');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-151', '望廈山環境資訊中心', '', '學', '澳門半島', '望廈炮台斜坡', 22.207151, 113.548981, '[]', '市政署核心環境宣傳教育場館。每學年推出多項圍繞城市清潔及愛護環境的專題推廣活動，供本地註冊學校及非牟利團體（15至40人）預約導賞員帶領參觀', '', '週二至週日 09:00–13:00、14:30–17:30（逢週一休息，若週一爲公眾假期則順延一天）', '+853 2852 0559 / 8294 2692', '', 'published', '2026-11-10T06:37:16.422Z', '2026-11-10T06:37:16.422Z', '', '', '', '', 'https://www.iam.gov.mo/c/ecocenter/itemlist');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-152', '澳門科學館', '', '學', '澳門半島', '孫逸仙大馬路（近文化中心及漁人碼頭）', 22.186213, 113.557048, '[]', '展覽中心內設可持續發展及生態環保相關展覽（如3樓G11展廳等），並常年作爲社區綠色技能親子藝術嘉年華場地，透過互動科學展品普及環境科學知識', '', '週一至週三、週五至週日 10:00–18:00（逢週四及農曆除夕休館，公眾假期照常開放）', '', 'assets/catalog-118c99d2-0d56-5366-ad97-3e2bde2c6099.webp', 'published', '2026-11-10T06:37:16.421Z', '2026-11-10T06:37:16.421Z', '', '', '', '', 'https://www.msc.org.mo/zh');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-153', '魯班先師木工藝陳列館 （傳統木工工藝及體驗工作坊）', '', '學', '澳門半島', '庇山耶街39–41號之間', 22.195465816282677, 113.53885559340279, '[]', '位於1840年建立的上架行會館內，展示大型魯班鎖及80餘件傳統木器，傳承傳統木工與修物智慧；陳列館樓上每月定期舉辦“木工體驗工作坊”，市民可提前透過文化局報名參與', '', '週一、二、四至日 10:00–18:00（逢週三休館，公眾假期照常開放；週末及假期 11:00、15:00 設駐場導賞）', '+853 8399 6699', 'assets/catalog-0e847fbe-c7d9-58f2-9015-d7ed6d1a7268.webp', 'published', '2026-11-10T06:37:16.420Z', '2026-11-10T06:37:16.420Z', '', '', '', '', 'https://www.icm.gov.mo/cn/LuBan');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-154', '澳門樂施會“良食校園”教育項目', '', '學', '澳門半島', '皇朝宋玉生廣場258號建興龍廣場18樓F室（活動於室內或入校舉辦）', 22.189297, 113.551238, '[]', '面向高小至大專學生及成人（每場15至50人，時長1.5小時）推出兩大互動工作坊：《良食剩宴》探討糧食公義，傳授把剩食轉化爲資源的“再分配、再加值和再利用”搶救三招；《賣可可‧愈賣愈坎坷》與鮑思高青年服務網絡合辦，透過角色扮演認識全球可可種植與公平貿易', '', '週一至週五 09:00–13:00、14:00–18:00（週六、日及公眾假期休息）', '+853 2875 7750', '', 'published', '2026-11-10T06:37:16.419Z', '2026-11-10T06:37:16.419Z', '', '', '', '', 'https://www.oxfam.org.mo/');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-155', '市政署園林綠化廳——自然護理處', '', '學', '澳門半島', '何賢紳士大馬路政府（青茂）辦公大樓11樓（亦可於中華廣場、北區及中區市民服務中心辦理）', 22.212754, 113.542008, '[]', '爲學校、機構及團體（15至50人，須提前15個工作天申請；每人5澳門元，65歲以上長者及12歲以下小童免費，20人以上團體豁免收費）提供市政署導賞員帶隊服務，實地講解步行徑、濕地及香徑藥谷的生態科普知識', '', '週一至週四 09:00–13:00、14:30–17:45；週五 09:00–13:00、14:30–17:30（週末及公眾假期休息）', '+853 2888 0087', '', 'published', '2026-11-10T06:37:16.418Z', '2026-11-10T06:37:16.418Z', '', '', '', '', 'https://www.iam.gov.mo/nature');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-156', '澳門明愛凱暉生命教育資源中心', '', '學', '澳門半島', '澳門半島明愛服務點', NULL, NULL, '[]', '結合生命教育與環境保護，曾舉辦“綠源手作坊 DIY飲料提袋”等社區減塑手作活動', '', '按中心活動排期開放', '查詢電話：+853 2893 0362 / 2893 4109', '', 'published', '2026-11-10T06:37:16.417Z', '2026-11-10T06:37:16.417Z', '', '', '', '', 'https://www.caritas.org.mo');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-157', '石排灣自然教育中心', '', '學', '路環', '路環石排灣郊野公園內', NULL, NULL, '[]', '集科普教育與生態保育功能於一體的綜合場所，成爲公眾探索自然、學習澳門本土生態知識的重要教育基地', '', '週二至週日 10:00–17:00（逢週一休息，若週一爲公眾假期則順延休息日）', '+853 2888 0087', '', 'published', '2026-11-10T06:37:16.416Z', '2026-11-10T06:37:16.416Z', '', '', '', '', 'https://www.iam.gov.mo/c/park/itemlist');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-158', '路環金像農場 (Kam Seong Farm)', 'Kam Seong Farm', '學', '路環', '路環竹灣馬路（路環市區往竹灣泳池方向的中段路段）', 22.114921953532573, 113.55706862670004, '[]', '於2005年啓用、佔地約 7,000 平方米的生態農業教學場所。內設活動大棚、動物籠舍、堆肥制炭區、農作物展示區及團體宿營木屋，提供農耕體驗與動植物保育導賞', '', '每日 09:00–18:00（團體農耕導賞、宿營木屋或市民專題活動需預先申請）', '+853 2888 0087', 'assets/catalog-ec83f7d5-81de-56a5-a0d6-b2673c058e48.webp', 'published', '2026-11-10T06:37:16.415Z', '2026-11-10T06:37:16.415Z', '', '', '', '', 'https://www.iam.gov.mo/c/facility/detail/04cd4379-ed50-40f2-921d-8737a8628fd5');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-162', '澳門特別行政區政府環境保護局 (DSPA)', 'DSPA', '參與', '澳門半島', '馬交石炮台馬路32號至36號電力公司大樓1樓', 22.204229, 113.553908, '["社區"]', '澳門環境政策與資源回收的官方統籌部門。市民可參與**“環保FUN”積分計劃**、10個環保加Fun站回收與免費公眾導賞、32個流動回收車站點交投、電腦及通訊設備回收等', '', '週一至週四 09:00–13:00、14:30–17:45；週五 09:00–13:00、14:30–17:30（公眾假期除外）', '環保熱線：+853 2876 2626，總機：+853 2872 5134', '', 'published', '2026-11-10T06:37:16.414Z', '2026-11-10T06:37:16.414Z', '', '', '', '', 'http://www.dspa.gov.mo');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-163', '澳門免廢生活協會 (Zero Waste Life Association Macau)', 'Zero Waste Life Association Macau', '參與', '澳門半島', '會址（澳門半島）：大纜巷40號B地下；常年淨灘點（路環）：路環竹灣及譚公廟一帶海岸', 22.201669, 113.541543, '["社區"]', '倡導“源頭減廢”與閒置資源配對的本地核心環保團體。常年每月組織市民前往路環竹灣及譚公廟淨灘併發布年度海岸清潔數據報告，同時舉辦飲品膠樽升級再造置物袋工作坊，呼籲“維修優先、減少包裝”。', '', '【持續活躍 · 2025–2026年每月定期淨灘】

每月定期組織公眾海岸清潔及社區讀書會/手作工作坊', '', '', 'published', '2026-11-10T06:37:16.413Z', '2026-11-10T06:37:16.413Z', '', '', '', '', 'https://www.facebook.com/MacauFreeCycle/');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-164', '綠色未來 (Green Future Macau)', 'Green Future Macau', '參與', '澳門半島', '媽閣街6A', 22.188532, 113.534711, '["社區"]', '成立於2012年中的代表性青年環保社團，主要面向15至30歲青年，團隊涵蓋環境科學、公共衛生、生物資源及社工等跨界在職人士，致力於推動環保文化融入日常。', '', '依具體社區環保活動、攝影比賽及自然閱讀課程時間開放', '', '', 'published', '2026-11-10T06:37:16.412Z', '2026-11-10T06:37:16.412Z', '', '', '', '', 'https://www.facebook.com/greenfuturemo');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-165', '澳門環保志願者協會', '', '參與', '澳門半島', '澳門半島：慕拉士大馬路218號澳門日報大廈12樓（淨灘及農場活動延伸至路環）', 22.205398, 113.553642, '["社區"]', '凝聚市民身體力行改善環境的義工組織。常年開展兩大品牌項目：綠色關愛行動（組織淨灘、山行清道、路氹生態區及路環金像農場親子活動）與環保志願者培訓系列活動（舉辦專業講座及赴鄰近地區考察環保基建）。', '', '社團辦公及志願服務時段', '+853 2872 0120 / 2835 6429', '', 'published', '2026-11-10T06:37:16.411Z', '2026-11-10T06:37:16.411Z', '', '', '', '', 'https://www.facebook.com/VolunteerMacau/
https://www.volunteers.org.mo/index.php/index/association/association6');
INSERT OR IGNORE INTO places (id, name, en, cat, area, address, lat, lng, tags, description, story, hours, phone, image, status, created_at, updated_at, address_en, description_en, story_en, hours_en, website) VALUES ('catalog-166', '澳門低碳發展協會', '', '參與', '澳門半島', '士多鳥拜斯大馬路67-69號松柏新邨地下O座', 22.201854, 113.551821, '["社區"]', '配合特區政府推進綠色低碳建設及國家“雙碳”工作的非牟利團體。聯合主辦 MIECF“環保展臺嘉許獎及綠色電費回贈”，並提供碳信用額零售服務（支持購買風電項目碳信用額抵銷碳排）。', '', '週一至週五 09:30–18:00', '+853 2882 0495', '', 'published', '2026-11-10T06:37:16.410Z', '2026-11-10T06:37:16.410Z', '', '', '', '', 'https://www.mlcda.com/');
